  9	    static List<Integer> topoSort(DirectedGraph graph) {
 10	        int vertexCount = graph.vertexCount();
 11	        int[] indegree = buildIndegreeTable(graph);
 12	        Deque<Integer> queue = new ArrayDeque<>();
 13	        List<Integer> order = new ArrayList<>();
 14	
 15	        enqueueZeroIndegreeVertices(indegree, queue);
 16	
 17	        while (!queue.isEmpty()) {
 18	            int vertex = queue.remove();
 19	            order.add(vertex);
 20	            for (int next : graph.neighborsOf(vertex)) {
 21	                indegree[next]--;
 22	                if (indegree[next] == 0) {
 23	                    queue.add(next);
 24	                }
 25	            }
 26	        }
 27	
 28	        if (order.size() != vertexCount) {
 29	            throw new IllegalStateException("Topological sort requires a directed acyclic graph.");
 30	        }
 31	
 32	        return order;
 33	    }
