 35	    private static int[] buildIndegreeTable(DirectedGraph graph) {
 36	        int[] indegree = new int[graph.vertexCount()];
 37	        for (int vertex = 0; vertex < graph.vertexCount(); vertex++) {
 38	            for (int next : graph.neighborsOf(vertex)) {
 39	                indegree[next]++;
 40	            }
 41	        }
 42	        return indegree;
 43	    }
