 41	    private static final class KahnTopologicalSorter {
 42	        List<Integer> sort(DirectedGraph graph) {
 43	            int[] indegree = graph.buildIndegreeTable();
 44	            Deque<Integer> readyVertices = collectZeroIndegreeVertices(indegree);
 45	            List<Integer> order = new ArrayList<>(graph.vertexCount());
 46	
 47	            while (!readyVertices.isEmpty()) {
 48	                int vertex = readyVertices.removeFirst();
 49	                order.add(vertex);
 50	                for (int next : graph.neighborsOf(vertex)) {
 51	                    indegree[next]--;
 52	                    if (indegree[next] == 0) {
 53	                        readyVertices.addLast(next);
 54	                    }
 55	                }
 56	            }
 57	
 58	            validateAcyclic(graph, order);
 59	            return order;
 60	        }
 61	
 62	        private Deque<Integer> collectZeroIndegreeVertices(int[] indegree) {
 63	            Deque<Integer> readyVertices = new ArrayDeque<>();
 64	            for (int vertex = 0; vertex < indegree.length; vertex++) {
 65	                if (indegree[vertex] == 0) {
 66	                    readyVertices.addLast(vertex);
 67	                }
 68	            }
 69	            return readyVertices;
 70	        }
