 72	        private void validateAcyclic(DirectedGraph graph, List<Integer> order) {
 73	            if (order.size() != graph.vertexCount()) {
 74	                throw new IllegalStateException("Topological sort requires a directed acyclic graph.");
 75	            }
 76	        }
 77	    }
